import 'dart:convert';import 'package:http/http.dart' as http;import '../models/recordatorio.dart';import 'server_config.dart';
class ApiService {Future<Uri> _uri(String path) async=>Uri.parse('${await ServerConfig.getUrl()}$path');Future<void> test() async {final r=await http.get(await _uri('/health')).timeout(const Duration(seconds:8));if(r.statusCode!=200)throw Exception('Servidor respondio ${r.statusCode}');}Future<List<Recordatorio>> list() async {final r=await http.get(await _uri('/recordatorios'));if(r.statusCode!=200)throw Exception('No se pudo cargar');return (jsonDecode(r.body) as List).map((e)=>Recordatorio.fromJson(e)).toList();}Future<void> create(Map<String,dynamic> data) async {final r=await http.post(await _uri('/recordatorios'),headers:{'Content-Type':'application/json'},body:jsonEncode(data));if(r.statusCode!=201)throw Exception('No se pudo crear: ${r.body}');}Future<void> update(String id,Map<String,dynamic> data) async {final r=await http.patch(await _uri('/recordatorios/$id'),headers:{'Content-Type':'application/json'},body:jsonEncode(data));if(r.statusCode!=200)throw Exception('No se pudo actualizar');}Future<void> delete(String id) async {final r=await http.delete(await _uri('/recordatorios/$id'));if(r.statusCode!=200)throw Exception('No se pudo eliminar');}}